assets.styles.css:
/* Cloud Nine: a soft pastel sky, frosted panels and round corners. Every colour is a wash of the palette's own roles. */

/* The sky: three soft clouds of the brand, select and info hues over the base. */
[data-part="shell.canvas"], .scs .bgm {
  background:
    radial-gradient(ellipse 55% 45% at 12% 8%, color-mix(in srgb, var(--bk-role-brand) 45%, transparent), transparent 70%),
    radial-gradient(ellipse 45% 40% at 92% 18%, color-mix(in srgb, var(--bk-role-select) 40%, transparent), transparent 70%),
    radial-gradient(ellipse 60% 50% at 70% 100%, color-mix(in srgb, var(--bk-role-info) 35%, transparent), transparent 70%),
    var(--bk-surface-base) !important;
}

/* Round, soft corners on every control, card and panel. */
button[data-control], [data-control="chip"], [data-part="scene.hud"] > *, input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), textarea, select { border-radius: 12px !important; }
[data-part="library.card"], [data-part="scenes.card"], [data-part="scenes.hero"], [data-part="ui.dialog"], [data-part="scene.wings.panel"],
[data-part="settings.body"] section, [data-part="editor.section"], [data-part="shell.overlay.widget"] { border-radius: 20px !important; overflow: hidden; }

/* Frosted glass: panels float over the sky with a soft lift instead of a hard edge. */
[data-part="library.card"], [data-part="scenes.card"], [data-part="scenes.hero"], [data-part="editor.section"], [data-part="shell.overlay.widget"] {
  border-color: color-mix(in srgb, var(--bk-line-strong) 35%, transparent) !important;
  box-shadow: 0 1px 0 color-mix(in srgb, var(--bk-surface-panel) 90%, transparent) inset, 0 14px 34px -18px color-mix(in srgb, var(--bk-role-brand-deep) 45%, transparent) !important;
}
[data-part="scene.wings.panel"], [data-part="ui.dialog"] {
  background: color-mix(in srgb, var(--bk-surface-panel) 82%, transparent) !important;
  backdrop-filter: blur(18px) saturate(1.3);
  box-shadow: 0 24px 60px -24px color-mix(in srgb, var(--bk-role-brand-deep) 50%, transparent) !important;
}

/* Scene header and wing bar as one frosted strip. */
.scs .sh, .scs nav.rail { background: color-mix(in srgb, var(--bk-surface-panel) 70%, transparent) !important; backdrop-filter: blur(14px); border-color: color-mix(in srgb, var(--bk-line-strong) 30%, transparent) !important; }
.scs .sh .nm { font-family: var(--font-fancy) !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: none !important; font-size: 1.15em !important; }
[data-part="scene.wings"] button[data-control] { border-color: transparent !important; background: transparent !important; box-shadow: none !important; }
[data-part="scene.wings"] button[data-control]:hover { background: color-mix(in srgb, var(--bk-role-brand) 30%, transparent) !important; }
[data-part="scene.wings"] button[data-control][aria-pressed="true"], [data-part="scene.wings"] button[data-control][aria-expanded="true"] { background: var(--bk-role-brand) !important; color: var(--bk-text-on-tint) !important; }

/* Bubbles (Full Chat only; chat layouts keep their own message shapes): round, with a tucked corner towards the speaker. */
.scs > .play .msg .bub {
  border-radius: 22px 22px 22px 6px !important; border: 0 !important;
  background: color-mix(in srgb, var(--bk-surface-panel) 92%, transparent) !important;
  box-shadow: 0 10px 26px -16px color-mix(in srgb, var(--bk-role-brand-deep) 45%, transparent) !important;
}
.scs > .play .msg.user .bub { border-radius: 22px 22px 6px 22px !important; background: color-mix(in srgb, var(--bk-role-brand) 55%, var(--bk-surface-panel)) !important; }
.scs > .play .msg .por { border-radius: 28px !important; border: 3px solid var(--bk-surface-panel) !important; box-shadow: 0 6px 16px -8px color-mix(in srgb, var(--bk-role-brand-deep) 60%, transparent) !important; }
.scs > .play .msg .spk { font-family: var(--font-fancy) !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: none !important; }

/* The message box is a pill floating above the sky. */
.scs .dockbar { background: transparent !important; border: 0 !important; }
.scs .dockbar .cap { border-radius: 26px !important; border: 1px solid color-mix(in srgb, var(--bk-line-strong) 40%, transparent) !important; background: var(--bk-surface-field) !important; box-shadow: 0 16px 36px -18px color-mix(in srgb, var(--bk-role-brand-deep) 55%, transparent) !important; }

/* The dock floats as a frosted pill. */
[data-part="shell.nav"] nav { border-radius: 24px !important; border: 1px solid color-mix(in srgb, var(--bk-line-strong) 35%, transparent) !important; background: color-mix(in srgb, var(--bk-surface-panel) 78%, transparent) !important; backdrop-filter: blur(16px) saturate(1.3); box-shadow: 0 18px 40px -20px color-mix(in srgb, var(--bk-role-brand-deep) 55%, transparent) !important; }
[data-part="shell.nav.tile"], [data-part="shell.nav.overlay"] { border-radius: 16px !important; color: var(--bk-text-dim) !important; }
[data-part="shell.nav.tile"]:hover { background: color-mix(in srgb, var(--bk-role-brand) 28%, transparent) !important; color: var(--bk-text) !important; }
[data-part="shell.nav.tile"][aria-current="page"] { background: var(--bk-role-brand) !important; color: var(--bk-text-on-tint) !important; }

/* In the paper chat layouts the sheets and stamps get the same soft corners. */
.scs [data-chat-layout="letters"] .msg, .scs .sb-book, .scs .sb-page, .scs [data-chat-layout="notebook"] .alt-main { border-radius: 22px !important; }
.scs .sb-left { border-radius: 22px 0 0 22px !important; } .scs .sb-page.alt-main { border-radius: 0 22px 22px 0 !important; }
